84e47198820e1bfe3b889e17e35e9c146e55acfc.midiecho:
// MIDI Echo: every pad press also goes out as a MIDI note on a channel of its own, pad 1 as note 36 (C1, the General MIDI
// bass drum) up to pad 16 as note 51, with the pad's velocity, and a note off on release. A drum machine or a DAW track
// can so follow the pads next to the notes the parts send. The page MIDI ECHO CH in the BLECH menu picks the channel, 1 to
// 16, and 0 switches it off. The MIDI SEND FILTER in Global applies as to the firmware's own notes. A note off goes to
// the channel its note on went to, also when the channel changed in between.
let ch = korg.store.get(0, 0);
let page = korg.menu.add("MIDI ECHO CH", 0, 16, ch);
const sent = new Array(16);

korg.onEvent("pad", (index, down, velocity) => {
  if (down) {
    if (ch == 0) return;
    let v = velocity;
    if (v < 1) v = 1;
    korg.midi.noteOn(ch - 1, 36 + index, v);
    sent[index] = ch;
    return;
  }
  if (sent[index] > 0) korg.midi.noteOff(sent[index] - 1, 36 + index);
  sent[index] = 0;
});

korg.onEvent("menu", (id, value) => {
  if (id != page) return;
  ch = value;
  korg.store.set(0, ch);
  korg.store.save();
});

84e47198820e1bfe3b889e17e35e9c146e55acfc.motionclear:
// Motion Clear: deletes the motion sequence of the selected part from the BLECH menu, as Part Util CLEAR MOTION does
// (korg.motion.clearPart). Turning the page CLEAR MOTION up to 3 is the confirmation: on reaching 3 the motion of the
// selected part goes, with all parts selected the motion of every part. Turning it back below 3 arms it again, the values
// in between do nothing. Only the pattern in RAM changes, WRITE keeps it as for any other edit.
let page = korg.menu.add("CLEAR MOTION", 0, 3, 0);
let armed = 1;

korg.onEvent("menu", (id, value) => {
  if (id != page) return;
  if (value < 3) {
    armed = 1;
    return;
  }
  if (armed == 0) return;
  armed = 0;
  const part = korg.read.part();
  if (part < 16) {
    korg.motion.clearPart(part);
    return;
  }
  for (let p = 0; p < 16; p++) korg.motion.clearPart(p);
});

84e47198820e1bfe3b889e17e35e9c146e55acfc.sysinfo:
// System Info, an app under TOOLS: shows on which Electribe the plugin runs, the BLECHTRIBE version, how many insert and
// master effects and sample slots the firmware has, and whether the device runs on the adapter or on battery, with the
// battery level as the symbol top right shows it. All values are the firmware's own (korg.system); the screen is drawn
// again once a second, so plugging the adapter in or out shows up while the app is open.
korg.app("System Info", "TOOLS");
let isOpen = 0;
let next = 0;

function digits(n) {
  let d = 1;
  while (n >= 10) {
    n = n / 10;
    d += 1;
  }
  return d;
}

function version(v) {
  if (v == 0) {
    korg.display.text("BLECH -", 2, 14);
    return;
  }
  const major = v / 10000;
  const minor = (v / 100) % 100;
  const patch = v % 100;
  let x = 2 + 36;
  korg.display.textNumber("BLECH ", major, 2, 14);
  x += digits(major) * 6;
  korg.display.textNumber(".", minor, x, 14);
  x += 6 + digits(minor) * 6;
  korg.display.textNumber(".", patch, x, 14);
}

function draw() {
  korg.display.clear();
  const device = korg.system.device;
  if (device == 0) korg.display.text("HACKTRIBE", 2, 2);
  if (device == 1) korg.display.text("KORG SAMPLER (RED)", 2, 2);
  if (device == 2) korg.display.text("KORG SYNTH (BLUE)", 2, 2);
  version(korg.system.version);
  korg.display.textNumber("IFX ", korg.system.limits.ifxTypes, 2, 26);
  korg.display.textNumber("MFX ", korg.system.limits.mfxTypes, 62, 26);
  korg.display.textNumber("SAMPLE SLOTS ", korg.system.limits.samples, 2, 38);
  if (korg.system.power == 1) {
    korg.display.text("POWER ADAPTER", 2, 50);
  } else {
    korg.display.textNumber("BATTERY ", korg.system.battery, 2, 50);
    korg.display.text("/4", 2 + 48 + 6, 50);
  }
  next = korg.millis() + 1000;
}

korg.onEvent("open", () => {
  isOpen = 1;
  draw();
});

korg.onEvent("close", () => {
  isOpen = 0;
});

korg.onEvent("frame", () => {
  if (isOpen == 1 && korg.millis() >= next) draw();
});

84e47198820e1bfe3b889e17e35e9c146e55acfc.vumeter:
// VU Meter, an app under TOOLS: two bars show the output level the way the level meter LEDs do (korg.audio.level, the
// firmware's smoothed value, new every 40 ms), each with a mark that holds its peak for a second. Which side is left on
// the device is not checked yet, so the bars are named 1 and 2. Only a bar that changed is drawn again.
korg.app("VU Meter", "TOOLS");
const WIDTH = 108;
const shown = [-1, -1];
const mark = [-1, -1];
const peak = [0, 0];
const until = [0, 0];

function bar(side, level) {
  const y = 12 + side * 26;
  const w = level * WIDTH / 254;
  const p = peak[side] * WIDTH / 254;
  korg.display.clearRect(14, y, WIDTH + 1, 14);
  if (w > 0) korg.display.rect(14, y, w, 14);
  korg.display.rect(14 + p, y, 1, 14);
  shown[side] = level;
  mark[side] = peak[side];
}

function draw() {
  korg.display.clear();
  korg.display.text("1", 4, 15);
  korg.display.text("2", 4, 41);
  shown[0] = -1;
  shown[1] = -1;
}

korg.onEvent("open", () => {
  peak[0] = 0;
  peak[1] = 0;
  draw();
});

korg.onEvent("frame", () => {
  const now = korg.millis();
  for (let side = 0; side < 2; side++) {
    const level = korg.audio.level(side);
    if (level >= peak[side]) {
      peak[side] = level;
      until[side] = now + 1000;
    } else if (now >= until[side]) {
      peak[side] = level;
    }
    if (level != shown[side] || peak[side] != mark[side]) bar(side, level);
  }
});

results.8ea79256ab8ee154610ffcf4d52558759fa07ac2:
// PLAY-Takt: solange der Sequencer läuft, blinkt die PLAY-LED im Tempo des Patterns, bei STOP und Pause leuchtet sie
// ruhig. Dabei zeigt es die Timer der Plugin-API (API 11): `beat` kommt auf jede Viertel und macht die LED an,
// korg.afterSteps(2, off) macht sie zwei Schritte später wieder aus, so folgt das Blinken dem Tempo. STOP und Pause räumen
// den Timer mit korg.cancel ab. In der Pause blinkt die Firmware die PLAY-LED selbst, das Plugin setzt sie dort in jedem
// Rahmen wieder an.
let dark = -1;

function playLed(level) {
  korg.led(korg.led.PLAY, level);
  korg.led(korg.led.PLAY_BLUE, level);
}

function off() {
  playLed(0);
}

korg.onEvent("ready", () => { if (korg.transport == 0) playLed(255); });

korg.onEvent("beat", () => {
  korg.cancel(dark);
  playLed(255);
  dark = korg.afterSteps(2, off);
});

korg.onEvent("stop", () => {
  korg.cancel(dark);
  playLed(255);
});

korg.onEvent("frame", () => { if (korg.transport == 2) playLed(255); });

9765301a1cde1595abd5992a547cbfbe97a8ca5d.gatehold:
// Gate Hold (idea 72): in Gate Arp mode the note stays where the finger first touched, and moving the finger along X picks
// the Gate Arp rhythm of the pattern (the Pattern menu's GATE ARP, 0 to 49, left to right). Y stays the firmware's. Letting
// go of the touchpad puts back the rhythm the pattern had, so nothing changes unsaved. The touchpad mode is the firmware's
// and stays on until another mode key comes (measured in the emulator): GATE ARP sets Gate Arp, MASTER FX and TOUCH SCALE
// leave it, with SHIFT GATE ARP and MASTER FX open their menu pages and keep the mode. The plugin follows those keys and only
// holds the touch X (korg.touchLockX) in Gate Arp mode. The page GATE HOLD in the BLECH menu switches it on (1) and off (0).
const GATE_ARP = 11;
let on = korg.store.get(0, 1);
let page = korg.menu.add("GATE HOLD", 0, 1, on);
let gate = 0;
let shift = 0;
let holding = 0;
let base = 0;
let rhythm = -1;

function letGo() {
  if (!holding) return;
  if (rhythm >= 0 && rhythm != base) korg.seq.setPatternValue(GATE_ARP, base);
  korg.touchLockX(-1);
  holding = 0;
}

korg.onEvent("buttonPress", (key) => {
  if (key == korg.key.SHIFT) shift = 1;
  if (key == korg.key.GATE_ARP && !shift) gate = 1;
  if (key == korg.key.MASTER_FX && !shift) gate = 0;
  if (key == korg.key.TOUCH_SCALE) gate = 0;
  if (!gate) letGo();
});

korg.onEvent("buttonRelease", (key) => {
  if (key == korg.key.SHIFT) shift = 0;
  if (key == korg.key.TOUCHPAD) letGo();
});

// The first position plays the note and fixes it (the firmware counts X in 128 steps), the ones after pick the rhythm.
korg.onEvent("touch", (x, y, first) => {
  if (!on || !gate) return;
  if (first || !holding) {
    letGo();
    base = korg.pattern.current.gateArp;
    rhythm = -1;
    korg.touchLockX(x >> 3);
    holding = 1;
    return;
  }
  const r = (x * 50) >> 10;
  if (r == rhythm) return;
  rhythm = r;
  korg.seq.setPatternValue(GATE_ARP, r);
});

// A new pattern brings its own rhythm: that one comes back on release.
korg.onEvent("patternChange", () => {
  if (!holding) return;
  base = korg.pattern.current.gateArp;
  rhythm = -1;
});

korg.onEvent("menu", (id, value) => {
  if (id != page) return;
  on = value;
  korg.store.set(0, on);
  korg.store.save();
  if (!on) letGo();
});

9765301a1cde1595abd5992a547cbfbe97a8ca5d.momentmute:
// Momentary Mute, a wish from the community: mutes change only while PART MUTE is held. PART MUTE held, a pad switches its
// part on or off and the pads show the mutes; PART MUTE released, the pads trigger as in TRIGGER mode. All of it is the
// firmware's: PART MUTE switches the pad mode on its press and keeps it after the release (measured in the emulator), so
// the plugin only presses TRIGGER for the firmware when PART MUTE comes up (korg.pressKey). SHIFT + PART MUTE stays the
// firmware's, and another mode key pressed while PART MUTE is held keeps its mode. The page MOMENT MUTE in the BLECH menu
// switches it on (1) and off (0: PART MUTE stays a mode as without the plugin).
const MODES = [korg.key.PART_ERASE, korg.key.TRIGGER, korg.key.SEQUENCER, korg.key.KEYBOARD, korg.key.CHORD, korg.key.STEP_JUMP, korg.key.PATTERN_SET];
let on = korg.store.get(0, 1);
let page = korg.menu.add("MOMENT MUTE", 0, 1, on);
let shift = 0;
let held = 0;

korg.onEvent("buttonPress", (key) => {
  if (key == korg.key.SHIFT) shift = 1;
  if (key == korg.key.PART_MUTE) held = on && !shift ? 1 : 0;
  for (let i = 0; i < MODES.length; i++) {
    if (key == MODES[i]) held = 0;
  }
});

korg.onEvent("buttonRelease", (key) => {
  if (key == korg.key.SHIFT) shift = 0;
  if (key != korg.key.PART_MUTE || !held) return;
  held = 0;
  if (on) korg.pressKey(korg.key.TRIGGER);
});

korg.onEvent("menu", (id, value) => {
  if (id != page) return;
  on = value;
  korg.store.set(0, on);
  korg.store.save();
});

9765301a1cde1595abd5992a547cbfbe97a8ca5d.stepcopy:
// Step Copy: copies the steps of one bar of the pattern in RAM into another bar, so a figure recorded once does not have
// to be played in again. The pages in the BLECH menu: STEP COPY FROM the source bar (1 to 4), STEP COPY TO the target bar
// (1 to 4, 0 all bars after the source up to the pattern's length), STEP COPY what to copy (0 nothing, 1 the selected
// part, 2 all 16 parts). The copy runs once the dial has rested on 1 or 2 for 0.6 s, so the values passed on the way
// copy nothing; 0 and back copies again. Steps are copied whole (on, gate, velocity, trigger, the four note places).
// A target bar beyond the pattern's length lengthens the pattern to that bar (the Pattern menu's LENGTH setter).
// A source bar beyond the length copies nothing. Motion data and the part values stay as they are.
const BAR = 192;
let from = korg.store.get(0, 1);
let to = korg.store.get(1, 2);
let mode = 0;
let timer = -1;
let pageFrom = korg.menu.add("STEP COPY FROM", 1, 4, from);
let pageTo = korg.menu.add("STEP COPY TO", 0, 4, to);
let pageGo = korg.menu.add("STEP COPY", 0, 2, 0);
const steps = new Array(BAR);

function copyBar(part, src, dst) {
  korg.read.patternBytes(steps, -1, 2048 + 816 * part + 48 + BAR * src);
  korg.seq.writeSteps(steps, part, 16 * dst);
}

function copyParts(src, dst) {
  if (mode == 2) {
    for (let p = 0; p < 16; p++) copyBar(p, src, dst);
  } else {
    const part = korg.read.part();
    if (part < 16) copyBar(part, src, dst);
  }
}

function run() {
  timer = -1;
  if (mode == 0) return;
  const src = from - 1;
  let bars = korg.pattern.current.length;
  if (src >= bars) return;
  if (to > bars) {
    korg.seq.setPatternValue(2, to);
    bars = to;
  }
  if (to == 0) {
    for (let dst = src + 1; dst < bars; dst++) copyParts(src, dst);
  } else if (to - 1 != src) {
    copyParts(src, to - 1);
  }
}

korg.onEvent("menu", (id, value) => {
  if (id == pageFrom) {
    from = value;
    korg.store.set(0, value);
    korg.store.save();
  }
  if (id == pageTo) {
    to = value;
    korg.store.set(1, value);
    korg.store.save();
  }
  if (id == pageGo) {
    mode = value;
    korg.cancel(timer);
    timer = korg.after(600, run);
  }
});
